import {directorSummary,noteHTML} from './enhancements.mjs';
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n);
const percent=n=>n===null?'—':`${n>0?'+':''}${n.toFixed(1)}%`;
export function directorPanel(state,filters={}){const m=directorSummary(state,filters);return `<section class="card director-panel"><div class="section-head"><div><div class="eyebrow">DIRECTOR'S VIEW</div><h2 style="margin-top:6px">Trip cost performance</h2><p>Freight compared with its frozen estimate. Missing costs never become zero.</p></div><div class="buttons"><select id="directorPrincipal" class="roleSelect" aria-label="Director principal filter"><option value="">All principals</option>${state.principals.map(p=>`<option value="${p.id}" ${filters.principal===p.id?'selected':''}>${e(p.short)}</option>`).join('')}</select><select id="directorWarehouse" class="roleSelect" aria-label="Director warehouse filter"><option value="">All warehouses</option>${state.warehouses.map(w=>`<option value="${w.id}" ${filters.warehouse===w.id?'selected':''}>${e(w.name)}</option>`).join('')}</select></div></div><div class="director-metrics"><div><span>Weighted freight variance</span><strong class="${m.variancePct>0?'dangertext':''}">${percent(m.variancePct)}</strong><small>${m.comparable?money(m.variance)+' against '+money(m.budget)+' matched estimate':'No comparable cost-declared trips yet'}</small></div><div><span>Total actual trip cost</span><strong>${m.declared?money(m.totalActual):'—'}</strong><small>${m.declared} cost-declared / ${m.trips} dispatched trips</small></div><div><span>Holding, unloading & extras</span><strong>${m.declared?money(m.extras):'—'}</strong><small>Disclosed separately from freight variance</small></div><div><span>Cost data coverage</span><strong>${m.coverage===null?'—':m.coverage.toFixed(0)+'%'}</strong><small>${m.pending} pending declarations · ${m.overruns} freight overruns</small></div></div><div class="director-bottom"><span>${m.zeroOrMissingBaseline} declared trips excluded from percentage: zero/missing estimate. Positive variance means over estimate.</span><button class="textlink" data-action="enh:directorDetails">View trip breakdown ↗</button></div></section>`;}
export function masterView(state,{heading,button,badge}){return heading('Fleet & material masters','Maintain the assumptions behind every truck suggestion and load calculation.',button('Add truck type','enh:addTruck','primary'))+`<div class="notice"><span>Manager role edits masters. Changes require review on affected preparing shipments; dispatched trips and approved cost estimates keep their snapshots.</span></div><section class="card"><div class="section-head"><div><h2>Truck master</h2><p>Payload in kg · usable volume in m³ · sample base freight in INR.</p></div>${badge(state.trucks.length+' types','gray')}</div><div class="tablewrap"><table><thead><tr><th>TRUCK TYPE</th><th>PAYLOAD</th><th>USABLE VOLUME</th><th>BASE FREIGHT</th><th>STATUS</th><th></th></tr></thead><tbody>${state.trucks.map(t=>`<tr><td><b>${e(t.name)}</b><small>${t.id} · revision ${t.revision}</small></td><td>${t.capacity.toLocaleString('en-IN')} kg</td><td>${t.volume} m³</td><td>${money(t.rate)}</td><td>${badge(t.active?'Active':'Inactive',t.active?'':'gray')}</td><td>${button('Edit truck','enh:editTruck','smallbtn',`data-id="${t.id}"`)}</td></tr>`).join('')}</tbody></table></div></section><section class="card" style="margin-top:20px"><div class="section-head"><div><h2>Material dimensions</h2><p>Packed dimensions in cm · packed gross weight per unit in kg.</p></div>${badge('Volume calculated from dimensions','gray')}</div><div class="tablewrap"><table><thead><tr><th>MATERIAL / SKU</th><th>L × W × H</th><th>UNIT VOLUME</th><th>GROSS WEIGHT</th><th>UNIT GOODS VALUE</th><th></th></tr></thead><tbody>${state.skus.map(m=>`<tr><td><b>${e(m.name)}</b><small>${m.id} · revision ${m.revision}</small></td><td>${m.dimensions?`${m.dimensions.length} × ${m.dimensions.width} × ${m.dimensions.height} cm`:'Legacy volume · enter dimensions'}</td><td>${m.unitVolume.toFixed(5)} m³</td><td>${m.unitWeight} kg</td><td>${money(m.unitValue)}</td><td>${button('Edit material','enh:editMaterial','smallbtn',`data-id="${m.id}"`)}</td></tr>`).join('')}</tbody></table></div></section><section class="card" style="margin-top:20px"><div class="section-head"><div><h2>Route-rate context</h2><p>Sample principal-contract multipliers applied to each truck's base freight.</p></div></div><div class="tablewrap"><table><thead><tr><th>PRINCIPAL</th><th>ROUTE</th><th>BASE RATE MULTIPLIER</th><th>ESTIMATED TRANSIT</th></tr></thead><tbody>${state.routeRates.map(r=>`<tr><td>${e(state.principals.find(p=>p.id===r.principal)?.short)}</td><td>${e(r.route)}</td><td>${r.multiplier} ×</td><td>${r.leadDays} calendar days</td></tr>`).join('')}</tbody></table></div></section><div class="help">Dimensions represent packed units. Material goods value is not 3PL revenue. This example does not model axle limits, irregular geometry or guaranteed physical load arrangement.</div>`;}
export function noteWorkbench(state,{button,badge}){const cases=state.returns.filter(r=>r.status!=='Awaiting receipt');return `<section class="card" style="margin-top:20px"><div class="section-head"><div><h2>Credit / debit note preparation</h2><p>Accounts prepares → manager reviews → reconcile approved draft → close return.</p></div>${badge('Draft documents · no accounting posting','gray')}</div><div class="tablewrap"><table><thead><tr><th>RETURN / SOURCE</th><th>DRAFT NOTE</th><th>VALUE / STATUS</th><th>ACTIONS</th></tr></thead><tbody>${cases.map(r=>{const n=r.noteDraft;return `<tr><td><b>${r.id}</b><small>${r.shipment} · ${r.sku}</small></td><td>${n?`<b>${e(n.reference)}</b><small>${e(n.type)} · v${n.revision} · ${e(n.issuer)}</small>`:'Not prepared'}</td><td>${n?`${money(n.total)}<small>${e(n.status)}</small>`:r.note?'Legacy reconciliation reference':'Awaiting draft'}</td><td><div class="buttons">${r.status!=='Closed'?button(n?'Edit draft':'Prepare note','enh:prepareNote','smallbtn',`data-return="${r.id}"`):''}${n?button('View / download','enh:viewNote','smallbtn',`data-return="${r.id}"`):''}${n&&n.status==='Draft'&&r.status!=='Closed'?button('Approve draft','enh:approveNote','smallbtn',`data-return="${r.id}"`):''}</div></td></tr>`;}).join('')||'<tr><td colspan="4" class="empty">Inspect a linked customer return to prepare its credit or debit note.</td></tr>'}</tbody></table></div></section>`;}
export function enhancementAction(action,attrs,c){const {state,modal,actionForm,field,textfield,button,badge,filters,download,run}=c;
 const number=(label,name,value,hint='')=>field(label,name,value,'number',hint).replace('step="1"','step="0.01"');
 if(action==='enh:addTruck'||action==='enh:editTruck'){const t=state.trucks.find(t=>t.id===attrs.id);return actionForm(t?'Edit '+t.name:'Add truck type',`${field('Truck type name','name',t?.name||'') }<div class="formgrid">${number('Payload capacity (kg)','capacity',t?.capacity||'')}${number('Usable volume (m³)','volume',t?.volume||'')}${number('Base freight (INR)','rate',t?.rate||'')}</div><div class="field"><label for="truckActive">Availability</label><select id="truckActive" name="active"><option value="true" ${t?.active!==false?'selected':''}>Active</option><option value="false" ${t?.active===false?'selected':''}>Inactive</option></select></div><div class="help">Active preparing plans using this truck require planner review after an edit. Frozen freight estimates do not change.</div>`,'saveTruck',p=>({...p,id:t?.id,capacity:Number(p.capacity),volume:Number(p.volume),rate:Number(p.rate),active:p.active==='true'}));}
 if(action==='enh:editMaterial'){const m=state.skus.find(m=>m.id===attrs.id);return actionForm('Edit '+m.id+' packed dimensions',`${field('Material name','name',m.name)}<div class="formgrid">${number('Packed length (cm)','length',m.dimensions?.length||'')}${number('Packed width (cm)','width',m.dimensions?.width||'')}${number('Packed height (cm)','height',m.dimensions?.height||'')}${number('Gross weight per unit (kg)','unitWeight',m.unitWeight)}${number('Goods value per unit (INR)','unitValue',m.unitValue)}</div><div class="help">Volume = length × width × height ÷ 1,000,000. No manual volume override. Changes flag affected preparing loads for review.</div>`,'saveMaterial',p=>({...p,id:m.id,...Object.fromEntries(['length','width','height','unitWeight','unitValue'].map(k=>[k,Number(p[k])]))}));}
 if(action==='enh:reviewMaster'){if(run('reviewMaster'))return;return;}
 if(action==='enh:prepareNote'){const r=state.returns.find(r=>r.id===attrs.return),n=r.noteDraft,s=state.shipments.find(s=>s.id===r.shipment),m=state.skus.find(m=>m.id===r.sku);return actionForm('Prepare draft note · '+r.id,`<div class="help">Draft only, prepared by 3PL. Enter the actual authorized issuer and counterparty. Editing invalidates internal approval.</div><div class="field"><label for="noteKind">Note type</label><select id="noteKind" name="noteType"><option ${n?.type==='Credit note'?'selected':''}>Credit note</option><option ${n?.type==='Debit note'?'selected':''}>Debit note</option></select></div><div class="formgrid">${field('Draft note reference','reference',n?.reference||`DRAFT-${r.id}`)}${field('Source invoice reference','invoiceReference',n?.invoiceReference||s.documents.find(d=>d.kind==='invoice')?.reference||'')}</div>${field('Issuer / authorized entity','issuer',n?.issuer||state.principals.find(p=>p.id===r.principal).name)}${field('Recipient / counterparty','recipient',n?.recipient||s.destination)}<div class="formgrid">${field('Note quantity','quantity',n?.quantity||r.expected,'number')}${number('Unit rate (INR)','unitRate',n?.unitRate??m.unitValue)}${number('Tax amount (manually supplied, INR)','taxAmount',n?.taxAmount??0)}</div>${textfield('Reason, perspective and principal authorization','reason',n?.reason||r.reason)}<div class="help">Tax is a manual amount, not a calculated statutory rate. The draft total is quantity × rounded unit rate + manually supplied tax. No stock movement or financial posting is created.</div>`,'prepareNote',p=>({...p,returnId:r.id,quantity:Number(p.quantity),unitRate:Number(p.unitRate),taxAmount:Number(p.taxAmount)}),'Save draft note');}
 if(action==='enh:approveNote'){return actionForm('Manager review · draft note',textfield('Approval rationale and issuer authorization reviewed','reason','','Internal review only; this does not legally issue the note.'),'approveNote',p=>({...p,returnId:attrs.return}),'Approve draft');}
 if(action==='enh:viewNote'){const r=state.returns.find(r=>r.id===attrs.return),n=r.noteDraft;return modal(`${n.reference} · ${n.type}`,`<div class="notice">Draft / demonstration · ${e(n.status)} · version ${n.revision}</div><div class="note-paper"><div class="row"><h3>${e(n.type)}</h3><b>${money(n.total)}</b></div><div class="line"></div><p><b>Issuer:</b> ${e(n.issuer)}<br><b>Recipient:</b> ${e(n.recipient)}<br><b>Source invoice:</b> ${e(n.invoiceReference)}<br><b>Return / shipment:</b> ${r.id} / ${r.shipment}</p><div class="line"></div><p>${n.quantity} × ${e(n.sku)} @ ${money(n.unitRate)}<br>Subtotal ${money(n.subtotal)}<br>Manual tax ${money(n.taxAmount)}<br><b>Draft total ${money(n.total)}</b></p><p style="margin-top:15px">${e(n.reason)}</p><div class="line"></div><p class="small muted">Prepared by ${e(n.preparedBy)}<br>Internal review: ${e(n.approvedBy||'Pending')}</p></div><div class="help">Download the printable HTML, open it in a browser and use Print / Save as PDF. It remains watermarked as a draft.</div>`,()=>{download(`${n.id}-v${n.revision}.html`,noteHTML(n),'text/html');return true;},'Download printable note');}
 if(action==='enh:directorDetails'){const m=directorSummary(state,filters);return modal('Director · trip cost breakdown',`<div class="help">Weighted variance = (sum actual freight − sum matched freight estimates) ÷ sum matched estimates × 100. It is not the average of trip percentages.</div><div class="tablewrap"><table><thead><tr><th>TRIP</th><th>FREIGHT ESTIMATE</th><th>ACTUAL FREIGHT</th><th>VARIANCE</th></tr></thead><tbody>${m.rows.map(t=>`<tr><td>${t.id}<small>${e(t.route)}</small></td><td>${Number.isFinite(t.estimate)?money(t.estimate):'Missing'}</td><td>${t.costs?money(t.costs.freight):'Pending'}</td><td>${t.costs&&t.estimate>0?percent((t.costs.freight-t.estimate)/t.estimate*100):'Not comparable'}</td></tr>`).join('')||'<tr><td colspan="4">No dispatched trips in this scope.</td></tr>'}</tbody></table></div><div class="help">Actual total trip cost includes other declared charges; only freight is compared with the current freight-only estimate.</div>`);}
}
